CREATE DATABASE IF NOT EXISTS smarty;

USE smarty;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS articles_categories;
DROP TABLE IF EXISTS articles;
DROP TABLE IF EXISTS categories;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE articles (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    description TEXT NOT NULL,
    views_count INT UNSIGNED DEFAULT 0,
    image_url VARCHAR(255) DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE categories (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE articles_categories (
    article_id INT UNSIGNED NOT NULL,
    category_id INT UNSIGNED NOT NULL,
    PRIMARY KEY (article_id, category_id),
    FOREIGN KEY (article_id) REFERENCES articles(id),
    FOREIGN KEY (category_id) REFERENCES categories(id)
);

INSERT INTO categories (id, title, description) VALUES
(1, 'море', 'Статьи о морских побережьях, океанах, прибрежной жизни и подводном мире.'),
(2, 'горы', 'Материалы о вершинах, альпинизме, горных тропах и высокогорных пейзажах.'),
(3, 'лес', 'Публикации о лесах, дикой природе, тропах среди деревьев и экосистемах под кронами.'),
(4, 'пустыня', 'Рассказы о пустынях, дюнах, оазисах и жизни в засушливых ландшафтах.');

INSERT INTO articles (id, title, content, description, views_count, image_url) VALUES
(1, 'Шёпот прибоя на рассвете',
'Утро на морском берегу начинается задолго до того, как солнце поднимется над горизонтом. Туман стелется низко над водой, и только редкий крик чайки нарушает тишину. Песок ещё влажный от ночной прилива, а в каждой впадине остаются крошечные лужицы, в которых отражается бледное небо. Море дышит ровно и размеренно: волны накатывают на берег, отступают, снова приходят — словно огромное сердце, бьющееся в такт времени. Рыбаки давно знают эти часы: рыба смелее выходит к поверхности, вода прозрачнее, и можно разглядеть тёмные пятна камней под самой кромкой. Соль в воздухе ощущается на губах, в волосах, в складках одежды. Дети, если они приходят сюда с родителями, бегают по кромке, оставляя следы, которые через минуту смывает следующая волна. Старые волны оставляют на песке узоры — тонкие линии, спирали, разветвления, как карта невидимых течений. Вдали виднеется силуэт парусника: медленно, почти незаметно он скользит вдоль горизонта. Море не спешит и не требует от человека ответа — оно просто есть. И в этом присутствии многие находят то, чего не хватает в городе: пространство, звук, запах, ощущение границы между сушей и бездной. Когда солнце наконец вспыхивает золотом, вода превращается в дорожку света, уходящую вдаль. В этот момент берег кажется началом большого пути — туда, где небо сливается с морем, а мысли становятся такими же широкими, как открытая вода.',
'Рассвет на побережье: прилив, чайки и первые лучи над горизонтом.', 142, 'https://picsum.photos/400'),

(2, 'Вершина, к которой ведёт тропа',
'Горная тропа никогда не бывает прямой. Она зигзагает между валунами, огибает осыпи, то поднимается круто, то выравнивается на коротком плато, где можно перевести дух. Воздух с каждым сотнем метров становится суше и прозрачнее; запах хвои сменяется запахом камня и снега, который ещё лежит в тени на северных склонах. Альпинисты идут цепочкой не столько из дисциплины, сколько из уважения к месту: здесь ошибка стоит дорого, и каждый шаг требует внимания. Под ногами хрустит щебень, иногда скользит мокрая трава после внезапного грозового ливня. Вдалеке видны другие вершины — они кажутся близкими, но расстояние в горах обманчиво. Облака накрывают гребень неожиданно: за минуту солнце исчезает, температура падает, и мир сужается до нескольких метров видимости. Опытные путники знают: в такую погоду лучше остановиться, согреться, дождаться прояснения. На перевале часто встречают таблички, каменные курганы, ленточки — следы тех, кто прошёл до вас. Горы помнят каждого, но никому не открывают все свои тайны сразу. Подъём учит терпению: нельзя форсировать дыхание, нельзя игнорировать сигналы тела. Когда наконец открывается вид с вершины — долины, озёра, дальние хребты в голубой дымке — наступает редкая тишина внутри. Не крик радости, а тихое признание: ты дошёл, но горы остались больше тебя. Спуск иногда сложнее подъёма: усталость притупляет внимание, камни сыплются под ногами. И всё же тропа ведёт вниз, к огню, к чаю, к разговорам в приюте, где снова смеются и делятся историями. Горы отпускают, но зовут вернуться.',
'Подъём по горной тропе: перевалы, облака и вид с вершины.', 287, 'https://picsum.photos/400'),

(3, 'Свет сквозь кроны хвойного бора',
'Лес встречает не громом, а запахом. Смола, мох, влажная земля, чуть сладковатый аромат листвы — всё это смешивается в один неповторимый фон, который узнаёшь даже с закрытыми глазами. Под ногами мягкий наст из прошлогодних иголок, между корнями пробиваются клюква и черника, в тени растут грибы, и только знающий человек отличит съедобный от опасного. Птицы перекликаются на разных ярусах: где-то высоко стучит дятел, ниже воркует горлица, в кустах шуршит то, что лучше не тревожить без нужды. Свет в лесу не падает сверху столбом — он рассыпается, ломается, играет на стволах берёз и сосен, рисует пятна на тропе. Тропа здесь старая: углублена, обросла мхом по краям, местами пересечена ручьём на бродах из камней, уложенных руками давно ушедших хозяев этих мест. Лес живёт своим ритмом: утром — пение, днём — знойная тишина в полдень, вечером — треск веток и первые звёзды сквозь просветы. Звери оставляют следы: когтистые царапины на коре, помёт у поваленного дерева, шерсть на изгибе ветки. Человек в лесу гость, и хороший гость ходит тихо, не ломает сучьев ради забавы, забирает с собой только воспоминания и фотографии. Дождь в лесу особенный: капли гасят в листве, стекают по стволам, наполняют ручьи за считаные минуты. После дождя воздух становится кристальным, и кажется, что деревья стали выше. Зимой лес другой — белый, звонкий, с треском мороза на ветках. Но и тогда под снегом жива земля, и весна неизбежно вернёт зелень. Лес учит смотреть внимательно: на мелочи, на следы, на то, как медленно и уверенно растёт жизнь без спешки.',
'Хвойный бор: запах смолы, тропы, птицы и свет между кронами.', 95, 'https://picsum.photos/400'),

(4, 'Дюны и тень от верблюжьей каравана',
'Пустыня не пуста — в ней просто другая шкала жизни. Днём солнце поднимает температуру так, что воздух дрожит над песком, и горизонт расплывается, как в миражах. Дюны меняют очертания от ветра: вчерашний гребень сегодня сглажен, у подножия появились новые рябчики, как отпечатки невидимой руки. Верблюжий караван движется медленно, в ритме, выверенном веками: не спешить, беречь воду, идти в тень самых высоких барханов ранним утром и поздним вечером. Скорпионы и ящерицы прячутся под камни, корни редких кустов уходят вглубь на метры, туда, где влага ещё держится. Ночью пустыня преображается: небо густое от звёзд, песок остывает, слышно, как шелестит что-то маленькое между зёрнами. Кочевники знают созвездия лучше городских жителей — по ним ориентируются, когда днём нет ни дерева, ни камня на примет. Оазис — не миф, а точка на карте надежды: пальмы, колодец, шёпот людей, которые делятся водой с путником по закону гостеприимства. Песок бывает рыжим, белым, почти чёрным вулканическим — и каждый оттенок по-своему ослепляет в полдень. Песчаная буря приходит без предупреждения: небо желтеет, ветер режет лицо, мир сжимается до размера платка на глазах. Выживают те, кто сел, прикрылся, дождался. После бури воздух пахнет громом и железом, следы стираются, и пустыня снова кажется нетронутой. Пустыня учит скромности: здесь человек не хозяин, а прохожий, которому разрешают идти, если он уважает жажду, солнце и тишину. И в этой тишине многие слышат себя яснее, чем в шуме больших городов.',
'Пустынный день: дюны, караван, оазис и звёздная ночь над песком.', 203, 'https://picsum.photos/400'),

(5, 'Горный ручей в зелёной долине',
'Между двумя хребтами лежит долина, куда стекают ручьи с каменистых склонов. Вода холодная даже в июле — она только что вышла из-под снега и льда наверху. Ручей не спешит: он петляет, несёт в себе песчинки и крупинки слюды, журчит на перекатах, затихает в заводях, где растут ивы и осока. Берега поросли травой и кустарником, а выше, на склонах, начинается лес — сначала редкий, берёзовый, потом густой хвойный пояс. Горные пастухи иногда загоняют сюда стада на лето: колокольчики звенят, собаки лают, дым от костра поднимается тонкой нитью. Воздух в долине пахнет сеном, мокрым камнем и дымом. Камни в русле округлые — их терли века, и теперь на них удобно сидеть, снимая обувь, чтобы ощутить ледяную воду по щиколотку. Рыба здесь мелкая, но проворная; чаще всего её видят только как быструю тень. На склонах видны следы коз и, если повезёт, серны. Тропа вдоль ручья — самый старый путь через горы: так ходили торговцы, бежавшие от непогоды, влюблённые пары из соседних деревень. Вечером долина наполняется тенью раньше, чем вершины теряют последний свет: солнце уходит за гребень, и сразу становится прохладно. Ночью слышен совиный крик, шорох в кустах, редкий плеск бобра, если он есть в этих местах. Утро начинается с росы на траве и с тумана, стелющегося по руслу, пока солнце снова не поднимется достаточно высоко. Долина — место, где горы и лес встречаются без спора: камень даёт воду, вода кормит зелень, зелень держит склоны от осыпи. И человек, если он здесь появляется, чувствует себя частью этой простой, древней сделки.',
'Долина между хребтами: ледяной ручей, пастбища и лес на склонах.', 118, 'https://picsum.photos/400'),

(6, 'Скалы над морем: ветер и соль',
'Побережье здесь не песчаное, а каменистое: утёсы обрушиваются в море отвесными стенами, и только узкая тропа ведёт вдоль края. Ветер с океана бьёт без передышки, приносит брызги, которые ослепляют и обжигают кожу солью. Чайки кружат ниже, чем кажется с берега, — их крики смешиваются с гулом волн, разбивающихся о валуны внизу. Горные породы местами тёмные, местами выбелены налётом; в трещинах живут суккуленты и жёсткие травы, приспособленные к недостатку почвы. Альпинисты и моряки редко встречаются на одной тропе, но здесь их интересы сходятся: и тем, и другим нужно знать, где скользко, где ветер открыт полностью, где камень крошится под сапогом. Вид с утёса открывает бесконечную воду и далёкие паруса; за спиной — подъём к вершинам, где облака цепляются за скалы. Закат на таком берегу особенно яркий: солнце садится в море, небо горит, а тени на скалах становятся глубокими, почти фиолетовыми. Ночью слышен далёкий гудок корабля, редкий свет маяка, если он есть на мысе. Рыбаки знают эти места как опасные для швартовки, но богатые рыбой у самого дна. Путник, идущий по кромке, чувствует двойственность: с одной стороны — пропасть в воду, с другой — подъём в горы. Море зовёт вниз, горы — вверх, и человек идёт посередине, по узкой полосе земли, где соль и хвоя встречаются в одном дыхании. Такие места запоминаются надолго: они требуют уважения и дарят ощущение границы миров, где стихии не делят территорию, а спорят за каждый метр склона и каждый сантиметр прибоя.',
'Каменистое побережье у подножия гор: ветер, утёсы и брызги океана.', 176, 'https://picsum.photos/400'),

(7, 'Оазис: пальмы, колодец и зелёная кайма',
'В сердце пустыни, где дюны уходят за горизонт, внезапно появляется зелень. Не мираж — настоящие пальмы, низкие кусты, трава у колодца, вода которого холоднее, чем ожидаешь под таким солнцем. Оазис живёт за счёт подземных ключей: они бьют из глубины, питают кольцо растительности, и за пределами этой каймы снова начинается песок. Путники останавливаются здесь на день, иногда на неделю: пополняют запасы, чинят сбрую, делятся новостями. Птицы прилетают к воде — редкие в этих широтах, яркие, быстрые. Ночью в оазисе пахнет цветением и влагой, что кажется чудом после дневной жары. Лес в миниатюре — так можно назвать рощу: тень густая, воздух влажный, под ногами не песок, а почва с опавшими листьями. Местные знают, какие деревья посажены людьми век назад, а какие пришли сами по семенам, принесённым ветром и птицами. Граница между зеленью и пустыней резкая: шаг в сторону — и снова жар, свет, открытое небо. В оазисе учат беречь воду: не лить лишнего, не мыть технику в колодце, не загрязнять источник. Дети купаются в канаве-ааре, старики сидят в тени, молодые уходят в дюны на рассвете, когда можно идти без страха обезвоживания. Оазис — не только география, но и надежда: доказательство, что жизнь находит способ там, где кажется невозможной. И кто однажды напился здесь и отдохнул в тени, тот запомнит вкус воды и шелест пальм как самый дорогой дар пустыни. Отсюда уходят снова в песок, но уже с силой, которую даёт только место, где встретились пустыня и зелёная жизнь.',
'Оазис в пустыне: колодец, пальмы и узкая полоса жизни среди дюн.', 89, 'https://picsum.photos/400'),

(8, 'Пустынный берег: где песок встречает волну',
'Не всякое море омывает зелёные берега. Здесь пустыня подходит к самой воде: рыжий песок переходит в полосу прибоя, камни редки, зато ветер гонит волны длинными, ровными гребнями. Соль оседлает на всём — на коже, на ткани, на стекле, если оно есть. Днём песок жжёт ступни, море кажется спасением, но купаться опасно: течения сильные, берег пологий только на вид. Корабли вдали идут далёкими дорогами торговли между портами, зажатыми между пустынями и океаном. На берегу иногда находят ракушки, осколки керамики, редкие следы тех, кто жил здесь века назад, когда климат был иным. Ночью звёзды отражаются в мокром песке у кромки, и граница между небом и водой размывается. Птиц мало, зато чайки появляются стаями после шторма. Пустынный берег учит контрасту: жажда и полная вода рядом, жара и прохлада в одном горизонте. Кочевники редко ставят лагерь у самой кромки — слишком непредсказуем прилив, слишком открыт ветер. Но рыбаки знают лунные ночи, когда улов богат, и выходят на воду на лодках, легких, как чайки. Запах здесь смешанный: йод и сухая трава, брызги и пыль. Человек на таком берегу чувствует себя на стыке двух стихий, ни одна из которых не прощает беспечности. И всё же красота этого места суровая, честная: нет украшений, нет лишней зелени, только песок, солнце, солёная вода и небо, которое кажется выше, чем где-либо ещё. Кто выдерживает день здесь, тот запомнит, как море может быть не курортом, а границей мира, за которой начинается другой — сухой, бесконечный, но не менее великий.',
'Пустыня у океана: рыжий песок, прибой и суровый берег без растительности.', 154, 'https://picsum.photos/400'),

(9, 'Высокогорный лес на границе снега',
'Выше определённой отметки деревья растут иначе: ниже, корявее, стволы изогнуты ветром, крона редеет. Это уже не низменный бор, а высокогорный лес — место, где зима длиннее лета, и снег лежит в тени до июля. Тропа здесь идёт между стлаником, поднимается к перевалу, где начинаются голые камни. Воздух разрежен, дыхание учащается, но запах хвои остаётся — он гуще, смолистее. Звери редкие: росомаха, белка, иногда медведь, если лес ещё достаточно широк у подножия. Грибники сюда не ходят — слишком далеко и слишком капризна погода. Зато ботаники находят виды, которых нет в долинах: альпийские цветы, низкорослые кусты, лишайники на валунах. Склоны держат снег, задерживают воду, питают ручьи внизу — без этого леса долины были бы суше. Облака часто застревают на гребне, и тогда лес погружается во мглу, капли воды стучат по веткам, а через час может выглянуть солнце и радуга над пропастью. Горные леса страдают от пожаров и от слишком активного туризма: огонь идёт быстро в сухой сезон, следы кострищ остаются на десятилетия. Поэтому те, кто приходит, учатся тишине и правилам. С верхней точки леса видно, как под тобой расстилается море облаков, а выше — только пики и небо. Спуск обратно в густой зелёный пояс ощущается как возвращение в более мягкий мир, где снова поют птицы и где тропа не боится каждого порыва ветра. Высокогорный лес — хранитель воды и воздуха, узкая полоса жизни между камнем и небом, которую легко потерять, если не беречь.',
'Лес на склонах у линии снега: стланик, редкие звери и облака у гребня.', 231, 'https://picsum.photos/400'),

(10, 'Тропа от скал к морю через сосновый бор',
'Маршрут начинается высоко: скалы, ветер, вид на дальние вершины. Потом тропа уходит вниз, в сосновый бор, где пахнет смолой и тишина сгущается под кронами. Солнце пробивается редко, трава мягкая, под ногами хруст шишек. Ещё ниже — смешанный лес, берёзы, осинники, птицы громче. Слышен уже не только ветер в ушах, а что-то новое — глухой, ритмичный гул. Море близко. Запах соли появляется до того, как вода видна: он въедается в одежду, зовёт вперёд. Последний участок — спуск по песчаной тропе между кустарником, выход на открытый берег. Три мира за один день: камень, зелень, вода. Путники, знающие этот путь, берут воду в горах, еду в лесу не рвут без нужды, на берегу не оставляют мусор. Рассказывают, что тропа старая — ещё рыбаки ходили за смолой и за дровами, а потом сюда пришли туристы, и тропа стала шире, но не перестала быть узкой по смыслу. На перевале между лесом и скалами часто делают привал: смотрят назад на зелёный ковёр, вперёд — на синюю линию. Вечером на берегу костёр, если разрешён; иначе — только плед и звёзды. Волны накатывают, лес шумит вверху на склоне, скалы темнеют силуэтом. Человек, прошедший весь путь, чувствует связь между стихиями не в книге, а в ногах, в дыхании, в усталости и радости. Такие маршруты не для спешки: их идут, чтобы вспомнить, что земля не разорвана на отдельные картинки, а склеена тропами, ручьями, запахами, общим небом. И когда на закате море заливает золотом берег, а лес за спиной уже чёрный, кажется, что один день вместил целую жизнь перехода от высоты к безбрежности.',
'Один маршрут через горы, лес и выход к морскому берегу.', 312, 'https://picsum.photos/400'),

(11, 'Каменистое плато между пиками и дюнами',
'Высоко в горах есть места, где снега мало, ветра много, а растительность редкая — почти пустыня, только холоднее и каменистее. Плато тянется на километры: щебень, редкие колючие кусты, небо без облаков неделями. Зимой здесь бураны, летом — ослепительный свет и сухость, как в песках низменности, только вместо дюн — осыпи и валуны. Верблюдов нет, зато есть яки и дикие козлы, уверенно стоящие на отвесах. Вода встречается в редких ключах, их ищут по памяти предков, по едва заметным зелёным пятнам. Ниже, за обрывом, начинаются настоящие дюны — пустыня поднялась к горам по ветру, отложила песок в подножии хребта. Геологи объясняют это миллионами лет, путник чувствует иначе: как будто две стихии договорились о пограничье. Ночью звёзды яркие, холод пронизывает, костёр не греет так, как в долине. Днём тень от камня — единственное спасение. Тропа через плато короткая на карте и длинная по времени: каждый камень может быть последним опорным пунктом. Здесь редко встречаешь других людей; чаще — только следы, ветер, эхо собственных шагов. И всё же красота суровая: простые цвета, резкие линии горизонта, честный воздух. Кто проходит, тот понимает, почему пустыни и высокогорья рисуют вместе в воображении кочевников и альпинистов: оба ландшафта требуют расчёта, оба не терпят слабости, оба дарят вид, от которого становится тихо внутри. Спуск к дюнам — как переход в другой акт спектакля: песок снова мягок, звук иной, запах сухой травы. Но память о плато остаётся — каменной, ветреной, бескомпромиссной.',
'Высокогорное плато у границы с пустыней: камень, ветер и дюны в подножии.', 67, 'https://picsum.photos/400'),

(12, 'Четыре стихии одного путешествия',
'Представьте маршрут, который начинается у океана: солёный ветер, чайки, влажный песок. Вы идёте вдоль берега, пока скалы не поднимаются выше — море остаётся слева, звук прибоя сопровождает каждый шаг. Тропа уходит в горы: перевал, холодный ручей, облако, которое обволакивает лицо. На вершине — только камень и небо, дыхание короткое, мир огромный. Спуск ведёт в лес: запах смолы, мох, птицы, тень, где можно напиться из ручья и отдохнуть. Лес постепенно редеет, трава становится суше, деревья — реже, и впереди открывается пустыня: дюны, жар, миражи, оазис с пальмами, где вода сладкая, как награда. В оазисе вы встречаете караван: люди идут от пустыни к морю и обратно, веками связывая ландшафты торговлей и историями. Вы идёте с ними. Снова песок, снова солнце, потом — пустынный берег, где волна бьёт в рыжий песок. И снова море, замыкая круг. Четыре стихии — не метафора в книге, а реальная цепочка мест, которые можно пройти, если есть время, вода, карта и уважение к каждому участку. Море учит широте, горы — выносливости, лес — внимательности, пустыня — скромности. Вместе они составляют путешествие, которое невозможно забыть: не потому что легко, а потому что честно. Ночи у костра в лесу, рассвет на дюне, полдень на перевале, закат на волнах — всё это одна история, рассказанная землёй. И когда вы возвращаетесь домой, в городе всё ещё шумит, но вы слышите под шумом тот же прибой, тот же ветер в кронах, тот же песок под ногами. Четыре стихии остаются внутри, как четыре стороны компаса, по которым можно ориентироваться, когда забываешь, куда идти. Эта статья — о таком пути: единственном в своём роде, общем для всех, кто хоть раз решил не разделять мир на отдельные картинки, а связать их одной дорогой, одним дыханием, одной длинной, живой линией на карте и в памяти, от первого шага у воды до последнего взгляда на горизонт, где снова начинается море.',
'Круговой маршрут через море, горы, лес и пустыню — одна дорога, четыре ландшафта.', 401, 'https://picsum.photos/400');

